create extension if not exists "pgcrypto";
create type public.user_role as enum ('user','admin'); create type public.book_status as enum ('ongoing','completed','hiatus'); create type public.chapter_status as enum ('draft','scheduled','published'); create type public.book_kind as enum ('serial','epub','pdf'); create type public.library_status as enum ('reading','want_to_read','completed','favorite');
create table public.profiles (id uuid primary key references auth.users on delete cascade, username text unique not null check (username ~ '^[a-z0-9_]{3,30}$'), avatar_url text, bio text, role user_role not null default 'user', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.authors (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, bio text, avatar_url text, country text, birth_date date, created_at timestamptz not null default now());
create table public.publishers (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null);
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text);
create table public.books (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, original_title text, description text not null default '', cover_url text, banner_url text, author_id uuid references public.authors, publisher_id uuid references public.publishers, language text not null default 'tr', isbn text unique, status book_status not null default 'ongoing', book_type book_kind not null default 'serial', published_at timestamptz, views bigint not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.book_categories (book_id uuid references public.books on delete cascade, category_id uuid references public.categories on delete cascade, primary key(book_id,category_id));
create table public.chapters (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books on delete cascade, chapter_number integer not null check(chapter_number>0), title text not null, slug text not null, content text not null default '', status chapter_status not null default 'draft', views bigint not null default 0, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(book_id,chapter_number), unique(book_id,slug));
create table public.reading_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, book_id uuid not null references public.books on delete cascade, chapter_id uuid references public.chapters on delete set null, progress numeric(5,2) not null default 0 check(progress between 0 and 100), last_read_at timestamptz not null default now(), unique(user_id,book_id));
create table public.library (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, book_id uuid not null references public.books on delete cascade, status library_status not null default 'want_to_read', created_at timestamptz not null default now(), unique(user_id,book_id)); create table public.favorites (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, book_id uuid not null references public.books on delete cascade, created_at timestamptz not null default now(), unique(user_id,book_id)); create table public.ratings (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, book_id uuid not null references public.books on delete cascade, rating smallint not null check(rating between 1 and 5), created_at timestamptz not null default now(), unique(user_id,book_id));
create table public.comments (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, book_id uuid references public.books on delete cascade, chapter_id uuid references public.chapters on delete cascade, parent_id uuid references public.comments on delete cascade, content text not null check(char_length(content) between 1 and 5000), likes integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(book_id is not null or chapter_id is not null));
create table public.files (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books on delete cascade, file_type text not null check(file_type in ('epub','pdf','cover','banner','evidence')), file_url text not null, file_size bigint, created_at timestamptz not null default now()); create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, type text not null, title text not null, message text not null, read boolean not null default false, created_at timestamptz not null default now()); create table public.reports (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, comment_id uuid references public.comments on delete set null, reason text not null, status text not null default 'open', created_at timestamptz not null default now()); create table public.licenses (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books on delete cascade, license_type text not null, copyright_holder text not null, permission_reference text, start_date date, end_date date, notes text);
alter table public.profiles enable row level security; alter table public.authors enable row level security; alter table public.publishers enable row level security; alter table public.categories enable row level security; alter table public.books enable row level security; alter table public.chapters enable row level security; alter table public.book_categories enable row level security; alter table public.reading_progress enable row level security; alter table public.library enable row level security; alter table public.favorites enable row level security; alter table public.ratings enable row level security; alter table public.comments enable row level security;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create policy "public catalog" on public.books for select using (true); create policy "public authors" on public.authors for select using(true); create policy "public categories" on public.categories for select using(true); create policy "public chapters" on public.chapters for select using(status='published' or public.is_admin()); create policy "admin catalog" on public.books for all using(public.is_admin()) with check(public.is_admin()); create policy "admin chapters" on public.chapters for all using(public.is_admin()) with check(public.is_admin());
create policy "own profile select" on public.profiles for select using(id=auth.uid() or public.is_admin()); create policy "own profile update" on public.profiles for update using(id=auth.uid() or public.is_admin()) with check(id=auth.uid() or public.is_admin()); create policy "own progress" on public.reading_progress for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own library" on public.library for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own favorites" on public.favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own ratings" on public.ratings for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "public comments" on public.comments for select using(true); create policy "own comments insert" on public.comments for insert with check(user_id=auth.uid()); create policy "own comments update" on public.comments for update using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy "own comments delete" on public.comments for delete using(user_id=auth.uid() or public.is_admin());
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username) values(new.id, coalesce(nullif(new.raw_user_meta_data->>'username',''), 'reader_' || substring(new.id::text,1,8))); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create policy "admin profile management" on public.profiles for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets (id,name,public) values ('book-assets','book-assets',true) on conflict (id) do nothing;
create policy "public book assets" on storage.objects for select using (bucket_id='book-assets');
create policy "admin book assets" on storage.objects for all using (bucket_id='book-assets' and public.is_admin()) with check (bucket_id='book-assets' and public.is_admin());
create policy "public book categories" on public.book_categories for select using(true);
create policy "admin authors" on public.authors for all using(public.is_admin()) with check(public.is_admin());
create policy "admin publishers" on public.publishers for all using(public.is_admin()) with check(public.is_admin());
create policy "admin categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "admin book categories" on public.book_categories for all using(public.is_admin()) with check(public.is_admin());
create function public.protect_profile_role() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.role is distinct from new.role and not public.is_admin() then raise exception 'Only admins can change roles'; end if; return new; end; $$;
create trigger protect_profile_role before update on public.profiles for each row execute procedure public.protect_profile_role();
